 public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);applyHomePreferences();findViewById(R.id.settingsButton).setOnClickListener(v->settings());findViewById(R.id.darkModeButton).setOnClickListener(v->toggleDark());db=new WorkoutDb(this);status=findViewById(R.id.statusText);findViewById(R.id.managePlansButton).setOnClickListener(v->manage());findViewById(R.id.logWorkoutButton).setOnClickListener(v->log());findViewById(R.id.stepsButton).setOnClickListener(v->steps());findViewById(R.id.exportButton).setOnClickListener(v->export());findViewById(R.id.reportButton).setOnClickListener(v->report());sm=(SensorManager)getSystemService(SENSOR_SERVICE);step=sm.getDefaultSensor(Sensor.TYPE_STEP_COUNTER);}
