 void applyFontSize(View v,int offset){if(v instanceof TextView){TextView t=(TextView)v;Object original=t.getTag();float base;if(original instanceof Float)base=(Float)original;else{base=t.getTextSize()/getResources().getDisplayMetrics().scaledDensity;t.setTag(base);}t.setTextSize(Math.max(10,base+offset));}if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++)applyFontSize(g.getChildAt(i),offset);}}
