 void settings(){boolean en=english();LinearLayout box=new LinearLayout(this);box.setPadding(24,12,24,12);box.setOrientation(LinearLayout.VERTICAL);TextView langLabel=new TextView(this);langLabel.setText(en?"Language / زبان":"زبان / Language");box.addView(langLabel);Spinner lang=new Spinner(this);lang.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"فارسی","English"}));lang.setSelection(en?1:0);box.addView(lang);TextView fontLabel=new TextView(this);fontLabel.setText(en?"Font size":"اندازهٔ فونت");box.addView(fontLabel);SeekBar font=new SeekBar(this);font.setMax(8);font.setProgress(getSharedPreferences("fit_settings",0).getInt("font",0)+4);box.addView(font);TextView colorLabel=new TextView(this);colorLabel.setText(en?"Theme color":"رنگ تم");box.addView(colorLabel);Spinner color=new Spinner(this);color.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{en?"Blue":"آبی",en?"Green":"سبز",en?"Purple":"بنفش"}));color.setSelection(getSharedPreferences("fit_settings",0).getInt("accent",0));box.addView(color);new AlertDialog.Builder(this).setTitle(en?"Settings":"تنظیمات").setView(box).setPositiveButton(en?"Save":tr("Save","ذخیره"),(d,w)->{getSharedPreferences("fit_settings",0).edit().putString("language",lang.getSelectedItemPosition()==1?"en":"fa").putInt("font",font.getProgress()-4).putInt("accent",color.getSelectedItemPosition()).apply();applyHomePreferences();recreate();}).setNegativeButton(en?"Cancel":tr("Cancel","لغو"),null).show();}
